"""Thin paired lease and configured-root wiring tests; no solver invocation."""
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile
import unittest

ROOT = Path(__file__).resolve().parents[2]
PWSH = shutil.which("pwsh")

@unittest.skipUnless(PWSH, "PowerShell 7 required")
class PairedInheritedLeaseTests(unittest.TestCase):
    def test_actual_inherited_exit_and_noninherited_failure_propagation(self):
        code = 'param($Repo,$Draft)\n$ErrorActionPreference=\'Stop\';Set-StrictMode -Version Latest\n. (Join-Path $Repo \'common/host_execution_lease.ps1\')\nfunction Import-Function($Path,$Name){\n $tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseFile($Path,[ref]$tokens,[ref]$errors)\n if($errors.Count){throw ($errors|Out-String)}\n $node=$ast.Find({param($n)$n-is[Management.Automation.Language.FunctionDefinitionAst]-and$n.Name-eq$Name},$true)\n if(-not$node){throw (\'Missing function \'+$Name)}\n return [scriptblock]::Create($node.Extent.Text)\n}\n$workflow=Join-Path $Draft \'common/contracts/run_artifact_workflow.ps1\'\n. (Import-Function $workflow \'Assert-WorkflowFields\')\n. (Import-Function $workflow \'Assert-WorkflowWriterCompletion\')\n. (Import-Function $workflow \'Add-RunArtifactResourceRelease\')\nforeach($owner in @(\'paired_accelerator_static_field\',\'paired_accelerator_pulse\')){\n . (Import-Function (Join-Path $Draft "integrations/workflows/$owner/execute.ps1") \'Close-PairedHostStage\')\n $lease=@{inherited=$true;token=\'TEST_ONLY_PARENT\';environment_set=$false}\n $writerUnknown=$false;$hostReleaseUnknown=$false\n $nativeOperations=[Collections.Generic.List[object]]::new();$resourceReleases=[Collections.Generic.List[object]]::new()\n $nativeOperations.Add(@{operation_id=\'inert\';resource_release_id=\'TEST_ONLY_PARENT\';observation=@{exit_confirmed=$true;returncode=0;process_id=$PID;process_started_at_utc_ticks=(Get-Process -Id $PID).StartTime.ToUniversalTime().Ticks}})\n function Invoke-HostResourceTransaction {throw \'Inherited Exit must never release its parent\'}\n Close-PairedHostStage\n if($null-ne$lease-or$writerUnknown-or$hostReleaseUnknown-or$resourceReleases.Count-ne1-or$null-ne$resourceReleases[0].completion_receipt.host_release.result){throw \'Actual inherited null receipt was not preserved\'}\n $lease=@{inherited=$true;token=\'TEST_ONLY_PARENT\';environment_set=$false}\n $nativeOperations.Add(@{operation_id=\'second-inert\';resource_release_id=\'TEST_ONLY_PARENT\';observation=@{exit_confirmed=$true;returncode=0;process_id=$PID;process_started_at_utc_ticks=(Get-Process -Id $PID).StartTime.ToUniversalTime().Ticks}})\n Close-PairedHostStage\n Add-RunArtifactResourceRelease -ResourceReleases $resourceReleases -ReleaseId \'TEST_ONLY_PARENT\' -Receipt @{host_release=@{inherited=$true;token=\'TEST_ONLY_PARENT\';result=$null;error=$null};operations=@()}\n if($resourceReleases.Count-ne1-or$nativeOperations.Count-ne2){throw \'Repeated inherited stage lost operations or duplicated parent release\'}\n $rejected=$false;try{Add-RunArtifactResourceRelease -ResourceReleases $resourceReleases -ReleaseId \'TEST_ONLY_PARENT\' -Receipt @{host_release=@{inherited=$true;token=\'OTHER\';result=$null;error=$null}}}catch{$rejected=$true}\n if(-not$rejected){throw \'Conflicting duplicate release hidden\'}\n $completion=@{operations=@($nativeOperations.ToArray());resource_releases=@($resourceReleases.ToArray())}\n Assert-WorkflowWriterCompletion $completion -PowerShellOwner\n $completion.resource_releases[0].completion_receipt.host_release.inherited=$false\n $rejected=$false;try{Assert-WorkflowWriterCompletion $completion -PowerShellOwner}catch{$rejected=$true}\n if(-not$rejected){throw \'Null noninherited release accepted\'}\n $completion.resource_releases[0].completion_receipt.host_release.inherited=$true\n $completion.resource_releases[0].completion_receipt.host_release.result=@{status=\'acquired\';token=\'TEST_ONLY_PARENT\'}\n $rejected=$false;try{Assert-WorkflowWriterCompletion $completion -PowerShellOwner}catch{$rejected=$true}\n if(-not$rejected){throw \'Invented inherited transaction accepted\'}\n foreach($failure in @(\'null\',\'throw\',\'wrong_token\')){\n  $lease=@{inherited=$false;token=\'TEST_ONLY_PARENT\';environment_set=$false;completed_work_processes=@();state_path=\'TEST_ONLY\';role=\'SIMION\';stage=\'flight\'}\n  $writerUnknown=$false;$hostReleaseUnknown=$false\n  function Invoke-HostResourceTransaction {param($StatePath,$Request);if($failure-eq\'throw\'){throw \'PRIMARY_RELEASE_FAILURE\'};if($failure-eq\'wrong_token\'){return @{status=\'released\';token=\'OTHER\'}};return $null}\n  $caught=$null;try{Close-PairedHostStage}catch{$caught=$_}\n  if($null-eq$caught-or-not$writerUnknown-or-not$hostReleaseUnknown-or$null-eq$lease){throw \'Unconfirmed real release did not preserve protection\'}\n  if($failure-eq\'throw\'-and$caught.Exception.Message-ne\'PRIMARY_RELEASE_FAILURE\'){throw \'Primary error masked\'}\n }\n}\n\'PAIRED_INHERITED_AND_RELEASE_FAILURES=PASS\'\n'
        with tempfile.TemporaryDirectory() as directory:
            script = Path(directory) / "check.ps1"
            script.write_text(code, encoding="utf-8", newline="\n")
            result = subprocess.run([PWSH, "-NoProfile", "-File", str(script), "-Repo", str(ROOT), "-Draft", str(ROOT), "-Python", sys.executable], cwd=ROOT,capture_output=True, text=True, encoding="utf-8", timeout=30)
            self.assertEqual(result.returncode, 0, result.stdout + result.stderr)

    def test_static_configured_root_and_caller_environment_restore(self):
        code = "param($Repo,$Draft,$Python)\n$ErrorActionPreference='Stop';Set-StrictMode -Version Latest\n. (Join-Path $Repo 'common/contracts/run_artifact_support.ps1')\n. (Join-Path $Repo 'common/paths/workspace_paths.ps1')\n$owner=Join-Path $Draft 'integrations/workflows/paired_accelerator_static_field/execute.ps1'\n$tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseFile($owner,[ref]$tokens,[ref]$errors)\nif($errors.Count){throw ($errors|Out-String)}\n$pathNodes=$ast.EndBlock.Statements|Where-Object{$_.Extent.Text -match '^\\$pathArguments=|^if\\(\\$ArtifactRoot\\)|^\\$pathContext=|^\\$ArtifactRoot=|^\\$pathEnvironmentNames=|^\\$savedPathEnvironment='}\n$RepoRoot=$Repo;$ArtifactRoot='';$RunId='20261030_120000__test__python__path-fixture'\n$temp=Join-Path ([IO.Path]::GetTempPath()) ([guid]::NewGuid().ToString('N'))\n$original=Save-RunEnvironment -Names @('MASS_SPECTROMETRY_ARTIFACT_ROOT','MASS_SPECTROMETRY_EXECUTION_ROOT','MASS_SPECTROMETRY_HOST_RESOURCE_STATE_PATH','MASS_SPECTROMETRY_RUN_DIRECTORY','MASS_SPECTROMETRY_RUN_EXECUTION_DIRECTORY')\ntry{\n $env:MASS_SPECTROMETRY_ARTIFACT_ROOT=Join-Path $temp payload\n $env:MASS_SPECTROMETRY_EXECUTION_ROOT=Join-Path $temp execution\n $env:MASS_SPECTROMETRY_HOST_RESOURCE_STATE_PATH=Join-Path $temp host.sqlite3\n foreach($node in $pathNodes){. ([scriptblock]::Create($node.Extent.Text))}\n if($ArtifactRoot-ne$env:MASS_SPECTROMETRY_ARTIFACT_ROOT){throw 'Configured payload root ignored'}\n $body=@($ast.EndBlock.Statements|Where-Object{$_-is[Management.Automation.Language.TryStatementAst]-and$null-ne$_.Finally})[-1]\n foreach($node in $body.Body.Statements){if($node.Extent.Text-match '^\\$lease=Enter-HostResourceStage'){break};. ([scriptblock]::Create($node.Extent.Text))}\n if($env:MASS_SPECTROMETRY_RUN_DIRECTORY-ne(Join-Path $ArtifactRoot ('projects/instrument_assembly/runs/'+$RunId))){throw 'Canonical destination not scoped'}\n $env:MASS_SPECTROMETRY_ARTIFACT_ROOT='TEST_ONLY_MUTATION'\n . ([scriptblock]::Create($body.Finally.Statements[0].Finally.Statements[0].Extent.Text))\n if($env:MASS_SPECTROMETRY_ARTIFACT_ROOT-ne(Join-Path $temp payload)){throw 'Caller environment not restored'}\n 'STATIC_CONFIGURED_ROOT_AND_RESTORE=PASS'\n}finally{Restore-RunEnvironment -Names @($original.Keys) -Snapshot $original}\n"
        with tempfile.TemporaryDirectory() as directory:
            script = Path(directory) / "check.ps1"
            script.write_text(code, encoding="utf-8", newline="\n")
            result = subprocess.run([PWSH, "-NoProfile", "-File", str(script), "-Repo", str(ROOT), "-Draft", str(ROOT), "-Python", sys.executable], cwd=ROOT,capture_output=True, text=True, encoding="utf-8", timeout=30)
            self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
